PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE agent_runs (
	run_id VARCHAR(128) NOT NULL, 
	run_type VARCHAR(64), 
	start_time DATETIME, 
	end_time DATETIME, 
	status VARCHAR(64), 
	dry_run BOOLEAN, 
	jobs_scanned INTEGER, 
	salary_rejected INTEGER, 
	qualified_jobs INTEGER, 
	applications_submitted INTEGER, 
	blocked_count INTEGER, 
	failed_count INTEGER, 
	error_summary TEXT, 
	metadata_json JSON, 
	PRIMARY KEY (run_id)
);
CREATE TABLE application_events (
	id INTEGER NOT NULL, 
	application_id VARCHAR(128) NOT NULL, 
	from_status VARCHAR(64) NOT NULL, 
	to_status VARCHAR(64) NOT NULL, 
	reason VARCHAR(256), 
	payload JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(application_id) REFERENCES applications (application_id)
);
CREATE TABLE applications (
	application_id VARCHAR(128) NOT NULL, 
	job_id VARCHAR(128) NOT NULL, 
	resume_version_id VARCHAR(128), 
	submitted_at DATETIME, 
	status VARCHAR(64), 
	application_method VARCHAR(64), 
	confirmation_reference VARCHAR(256), 
	questions_answered JSON, 
	failure_reason TEXT, 
	dry_run BOOLEAN, 
	created_at DATETIME, resume_version VARCHAR(128), source_job_url TEXT, canonical_job_url TEXT, application_url TEXT, external_application_url TEXT, external_portal VARCHAR(128), started_at DATETIME, questions_detected JSON, confirmation_detected BOOLEAN, confirmation_text TEXT, final_url TEXT, verification_method VARCHAR(128), error_code VARCHAR(64), error_message TEXT, evidence_path TEXT, 
	PRIMARY KEY (application_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (job_id), 
	FOREIGN KEY(resume_version_id) REFERENCES resume_versions (version_id)
);
CREATE TABLE interview_packs (
	id INTEGER NOT NULL, 
	job_id VARCHAR(128) NOT NULL, 
	company VARCHAR(256) NOT NULL, 
	role VARCHAR(256) NOT NULL, 
	directory_path TEXT NOT NULL, 
	question_count INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(job_id) REFERENCES jobs (job_id)
);
CREATE TABLE job_evidence (
	id INTEGER NOT NULL, 
	job_id VARCHAR(128) NOT NULL, 
	observed_facts JSON, 
	inferred_signals JSON, 
	generated_actions JSON, 
	skills_found JSON, 
	tools_found JSON, 
	architecture_patterns JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (job_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (job_id)
);
CREATE TABLE job_scores (
	id INTEGER NOT NULL, 
	job_id VARCHAR(128) NOT NULL, 
	overall_score FLOAT NOT NULL, 
	architecture_score FLOAT, 
	cloud_score FLOAT, 
	oci_score FLOAT, 
	ai_score FLOAT, 
	agentic_ai_score FLOAT, 
	kubernetes_score FLOAT, 
	security_score FLOAT, 
	multicloud_score FLOAT, 
	experience_alignment FLOAT, 
	skill_alignment FLOAT, 
	passed_threshold BOOLEAN, 
	match_reasons JSON, 
	strengths JSON, 
	gaps JSON, 
	categories JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (job_id), 
	FOREIGN KEY(job_id) REFERENCES jobs (job_id)
);
CREATE TABLE jobs (
	job_id VARCHAR(128) NOT NULL, 
	title VARCHAR(256) NOT NULL, 
	company VARCHAR(256) NOT NULL, 
	location VARCHAR(256) NOT NULL, 
	work_mode VARCHAR(64), 
	experience_min FLOAT, 
	experience_max FLOAT, 
	experience_raw VARCHAR(128), 
	salary_min FLOAT, 
	salary_max FLOAT, 
	salary_currency VARCHAR(16), 
	salary_period VARCHAR(32), 
	salary_disclosed BOOLEAN, 
	salary_eligibility VARCHAR(32), 
	salary_raw_text VARCHAR(256), 
	posted_date VARCHAR(64), 
	url TEXT NOT NULL, 
	canonical_url TEXT, 
	jd_text TEXT, 
	source_query VARCHAR(256), 
	source_platform VARCHAR(64), 
	application_method VARCHAR(64), 
	status VARCHAR(64), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (job_id)
);
CREATE TABLE market_signals (
	id INTEGER NOT NULL, 
	signal_date VARCHAR(32) NOT NULL, 
	item_name VARCHAR(128) NOT NULL, 
	category VARCHAR(64) NOT NULL, 
	frequency INTEGER, 
	trend VARCHAR(32), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE resume_versions (
	version_id VARCHAR(128) NOT NULL, 
	job_id VARCHAR(128), 
	is_master BOOLEAN, 
	file_path_docx TEXT, 
	file_path_pdf TEXT, 
	checksum VARCHAR(64), 
	ats_score FLOAT, 
	ats_validation_details JSON, 
	tailoring_diff JSON, 
	created_at DATETIME, 
	PRIMARY KEY (version_id)
);
CREATE INDEX ix_jobs_company_title ON jobs (company, title);
CREATE INDEX ix_jobs_salary_eligibility ON jobs (salary_eligibility);
CREATE INDEX ix_jobs_status ON jobs (status);
CREATE INDEX ix_resume_versions_job_id ON resume_versions (job_id);
CREATE INDEX ix_market_signals_signal_date ON market_signals (signal_date);
CREATE INDEX ix_applications_status ON applications (status);
COMMIT;
